			dw kw_ztov, var_view_nl
			dw p_view_begin_r

; ============================================================
; sub line (turbo mode)
; ============================================================

p_view_line:

			; View.cls 68: Dim k As Integer

			; View.cls 69: If nl >= 150 Then Exit Sub
			dw kw_scpgevl, var_view_nl, 150
			dw kw_goto_iffalse, if184_1
			dw p_view_line_r
if184_1:

			; View.cls 70: k = nl * 4
			dw kw_4x, var_view_nl, var_view_line_k

			; View.cls 71: lb(k) = x0 : lb(k + 1) = y0 : lb(k + 2) = x1 : lb(k + 3) = y1
			dw kw_aset, arr_view_lb, var_view_line_k, var_view_line_x0
			dw kw_addl, var_view_line_k, 1, tmp0
			dw kw_aset, arr_view_lb, tmp0, var_view_line_y0
			dw kw_addl, var_view_line_k, 2, tmp0
			dw kw_aset, arr_view_lb, tmp0, var_view_line_x1
			dw kw_addl, var_view_line_k, 3, tmp0
			dw kw_aset, arr_view_lb, tmp0, var_view_line_y1

			; View.cls 72: nl = nl + 1
			dw kw_inc, var_view_nl
			dw p_view_line_r

